const fs=require('fs');const zlib=require('zlib');const bundle=[0,1,2,3].map(i=>fs.readFileSync(`fluent8-v2-${i}.txt`,'utf8')).join('').trim();const src=zlib.brotliDecompressSync(Buffer.from(bundle,'base64')).toString('utf8');eval(src);setTimeout(async()=>{const out={at:new Date().toISOString()};const base=`http://127.0.0.1:${process.env.PORT||3000}`;try{let r=await fetch(base+'/health');out.health={status:r.status,body:await r.text()};r=await fetch(base+'/api/coach',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name:'Deploy Test',lang:'en',scenario:'hotel',turn:0,userText:'I have a reservation',memory:{}})});out.coach={status:r.status,body:await r.text()}}catch(e){out.error=String(e&&e.stack||e)}try{fs.writeFileSync('/tmp/fluent8-selftest.json',JSON.stringify(out,null,2))}catch{}},1500);